/* Jay Ganesh Agency — Diwali 2027 live portal.
 * Same design as the original preview, but every record is read from and
 * saved to the organiser's Google Sheet through /api/handler (Apps Script).
 * No secrets or passwords are stored in this file. */
const e=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const rupee=n=>'₹'+Math.max(0,Number(n)||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const plan=m=>({first:m*1.5,other:m,packing:m*.5,payable:m*9.5,contribution:m*9,bonus:m,credit:m*10});
const data={pricing:[{id:'B1',name:'Crackers Box — ₹4,000 Value',advertised:4000,scheme:2000},{id:'B2',name:'Crackers Box — ₹6,000 Value',advertised:6000,scheme:3000},{id:'B3',name:'Crackers Box — ₹8,000 Value',advertised:8000,scheme:4000},{id:'B4',name:'Crackers Box — ₹10,000 Value',advertised:10000,scheme:5000},{id:'B5',name:'Crackers Box — ₹12,000 Value',advertised:12000,scheme:6000},{id:'B6',name:'New Arrival Fancy Box',advertised:15000,scheme:7500},{id:'B7',name:'Crackers Box — ₹20,000 Value',advertised:20000,scheme:10000},{id:'B8',name:'Diwali Special — Fully Fancy & Out',advertised:30000,scheme:15000}]};
const pill=(txt,cls)=>`<span class="pill ${cls||(/Pending|Draft|Awaiting|Leader Verified/.test(txt)?'pending':/Stop|Rejected|Under/.test(txt)?'stop':'' )}">${e(txt)}</span>`;
const btn=(txt,act,cls='btn btn-light btn-small',arg='')=>`<button class="${cls}" data-action="${act}" ${arg?`data-id="${e(arg)}"`:''}>${txt}</button>`;
const panel=(heading,inside,aside='')=>`<div class="panel"><div class="panel-header"><h2>${heading}</h2>${aside}</div>${inside}</div>`;
const kpi=(title,note,val)=>`<div class="kpi"><small>${e(title)}</small><strong>${e(val)}</strong><div class="hint">${note}</div></div>`;
function home(){const p=plan(ui.calc);return `<section class="hero"><div class="container"><div class="hero-content"><div class="hero-tag">✦ PRIVATE GROUP ARRANGEMENT · 2026–27</div><div class="eyebrow">Celebrate with thoughtful planning</div><h1>One plan.<br>One <em>brighter Diwali.</em></h1><p>Keep your group contributions, installments and order details organized in one simple, secure portal. Every contribution is recorded; every step stays clear.</p><div class="hero-actions"><button class="btn btn-primary" data-action="navigate" data-id="register">Register now <span>↗</span></button><button class="btn hero-ghost" data-action="navigate" data-id="scheme">Understand the scheme</button></div></div></div></section><div class="container"><div class="stats-strip"><div class="stat"><div class="stat-icon">▣</div><div><b>9 installments</b><small>One easy monthly plan</small></div></div><div class="stat"><div class="stat-icon">◎</div><div><b>Group managed</b><small>Transparent collections</small></div></div><div class="stat"><div class="stat-icon">✧</div><div><b>Diwali 2027</b><small>Plan ahead with clarity</small></div></div></div><section class="section"><div class="section-label">How it works</div><h2 class="section-title">Simple from start to celebration.</h2><p class="section-desc">A clear experience for members, group leaders and the organizer.</p><div class="three-grid"><div class="feature-card"><div class="feature-icon">✍</div><h3>01. Register</h3><p>Enter your basic details, choose your monthly amount and await approval from the main organizer.</p></div><div class="feature-card"><div class="feature-icon">▤</div><h3>02. Track payments</h3><p>View installment dates, verified contributions and your appointed group leader in one place.</p></div><div class="feature-card"><div class="feature-icon">▧</div><h3>03. Prepare your order</h3><p>Review box and list requirements, available scheme credit and the final amount payable.</p></div></div></section><section class="section" style="padding-top:0"><div class="two-grid"><div><div class="section-label">Plan your installments</div><h2 class="section-title">Know your numbers upfront.</h2><p class="section-desc">Choose your monthly amount in multiples of ₹100. The first payment includes a one-time packing charge; eligible members may receive a separate one-month bonus.</p><div class="callout info"><b>Important:</b> Packing charges do not become order credit. Bonus credit is subject to complete verified installments and admin approval.</div><div class="mt-20">${btn('Customer login','customer','btn btn-dark')}</div></div><div class="calculator"><div class="calc-head"><h3>EMI calculator</h3><div class="amount-input field"><label>Monthly EMI</label><input id="calc-amount" type="number" min="100" step="100" value="${ui.calc}"></div></div><div class="range-wrap"><input id="calc-slider" type="range" min="100" max="5000" step="100" value="${ui.calc}"><div class="row-between font-small muted"><span>₹100</span><span>₹5,000</span></div></div><div class="calc-grid"><div class="calc-number"><label>First installment</label><strong>${rupee(p.first)}</strong></div><div class="calc-number"><label>Next 8 each</label><strong>${rupee(p.other)}</strong></div><div class="calc-number"><label>Total payable</label><strong>${rupee(p.payable)}</strong></div><div class="calc-number highlight"><label>Potential scheme credit*</label><strong>${rupee(p.credit)}</strong></div></div><p class="muted font-small">*Subject to full verification and bonus approval; not guaranteed.</p></div></div></section></div>`;}
function scheme(){return `<main class="container page-main"><div class="page-heading"><div class="breadcrumbs">Home / Scheme</div><h1>Contribution plan & dates</h1><p>All calculations follow the submitted Diwali 2027 arrangement.</p></div><div class="two-grid"><div class="content-stack">${panel('Payment plan',`<div class="inline-list"><div><span>Monthly amount</span><strong>Choose ₹100, ₹200, ₹300...</strong></div><div><span>First installment</span><strong>1.5 × monthly EMI</strong></div><div><span>Installments 2–9</span><strong>Monthly EMI each</strong></div><div><span>One-time packing</span><strong>0.5 × monthly EMI</strong></div><div><span>Eligible bonus</span><strong>1 × monthly EMI</strong></div></div><div class="callout mt-16">The first installment contains packing charges, which are not included in usable scheme credit. A bonus is not automatic.</div>`)}${panel('Schedule',`<div class="inline-list"><div><span>Registration begins</span><strong>09 Nov 2026</strong></div><div><span>Registration deadline</span><strong>30 Nov 2026</strong></div><div><span>Final EMI deadline</span><strong>31 Jul 2027</strong></div><div><span>Order period</span><strong>Jun–Jul 2027*</strong></div></div><div class="muted font-small mt-16">*Opening date is set by the main organizer.</div>`)}</div><div class="content-stack">${panel('Example: ₹500 monthly EMI',`<div class="calc-grid"><div class="calc-number"><label>First installment</label><strong>₹750</strong></div><div class="calc-number"><label>Next eight total</label><strong>₹4,000</strong></div><div class="calc-number"><label>Paid including packing</label><strong>₹4,750</strong></div><div class="calc-number highlight"><label>Eligible credit + bonus</label><strong>₹5,000</strong></div></div><p class="font-small muted mt-16">₹4,500 contributions + ₹500 approved bonus = ₹5,000 potential credit.</p>`)}${panel('Order credit rule',`<p class="muted font-small">The discounted order value must use the full available verified EMI credit. An under-value order cannot be financially finalized.</p><div class="subtle"><div class="summary-line"><span>Available EMI credit</span><strong>₹5,000</strong></div><div class="summary-line"><span>Example advertised order value</span><strong>₹10,000</strong></div><div class="summary-line"><span>50% scheme price</span><strong>₹5,000</strong></div><div class="summary-line"><span>Extra amount payable</span><strong>₹0</strong></div></div><p class="muted font-small">Direct orders use regular pricing and no EMI credit.</p>`)}</div></div>${panel('Available cracker box types',`<div class="table-wrap"><table><thead><tr><th>Box type</th><th>Advertised value</th><th>EMI scheme price</th></tr></thead><tbody>${data.pricing.map(b=>`<tr><td>${e(b.name)}</td><td>${rupee(b.advertised)}</td><td><strong>${rupee(b.scheme)}</strong></td></tr>`).join('')}</tbody></table></div><p class="muted font-small mt-16">Direct orders use the full advertised value.</p>`)}<div class="mt-28">${btn('Register now','navigate','btn btn-dark','register')}</div></main>`;}

/* ================= LIVE PORTAL (Google Sheet via /api/handler) ================= */
const $=id=>document.getElementById(id);
const when=v=>v?new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'}):'—';
const roleNames={admin:'Main Admin',leader:'Group Leader',customer:'Customer'};
const tabs={
 admin:[['overview','Overview'],['registrations','Registrations'],['customers','Customers'],['groups','Groups'],['payments','Group collections'],['orders','Orders'],['security','PIN reset'],['settings','Settings & controls']],
 leader:[['overview','My group'],['review','Group payments'],['submit','Submit group collection'],['myemi','My EMI'],['record','Record my payment'],['history','My payment history'],['myorder','My order'],['grouporders','Group orders'],['pin','Change PIN']],
 customer:[['overview','Overview'],['record','Record payment'],['history','My payments'],['order','My order'],['pin','Change PIN']]
};
let ui={page:'home',tab:'overview',calc:500,toast:'',notice:'',orderId:''},server=null,me=null,renderToken=0;

async function api(action,fields={}){
 const r=await fetch('/api/handler',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-JGA-Request':'1'},body:JSON.stringify({action,...fields})});
 let d={};try{d=await r.json()}catch{}
 if(!r.ok){const err=new Error(d.error||'Request could not be completed');err.status=r.status;throw err}
 return d;
}
const table=(heads,rows,empty='No records yet.')=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}" class="empty">${e(empty)}</td></tr>`}</tbody></table></div>`;
const tr=(...cells)=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const errBox=err=>`<div class="callout stop-callout">${e(err.message||err)}</div>`;
const pinFields=`<div class="field"><label>Current 4-digit PIN</label><input name="currentPin" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required></div><div class="field"><label>New 4-digit PIN</label><input name="newPin" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required></div><div class="field"><label>Confirm new PIN</label><input name="confirm" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required></div>`;

function connChip(){if(!server)return '<span class="conn-chip bad">Connection unavailable</span>';return server.sheetsConnected?'<span class="conn-chip ok">Google Sheet connected</span>':'<span class="conn-chip bad">Setup pending</span>'}
function header(){const pg=ui.page;return `<header class="topbar"><div class="brand" data-action="home"><div class="brand-mark">✧</div><div><div class="brand-name">Jay Ganesh Agency</div><div class="brand-sub">Diwali 2027</div></div></div><nav class="nav"><button data-action="home" class="${pg==='home'?'active':''}">Home</button><button data-action="navigate" data-id="scheme" class="${pg==='scheme'?'active':''}">Scheme</button>${me?'':`<button data-action="navigate" data-id="register" class="${pg==='register'?'active':''}">Registration</button>`}${me?`<button data-action="dashboard" class="${pg==='dashboard'?'active nav-primary':'nav-primary'}">My dashboard</button><button data-action="logout">Log out</button>`:`<button data-action="navigate" data-id="login" class="${pg==='login'?'active nav-primary':'nav-primary'}">Login</button>`}${connChip()}</nav></header>`;}
function footer(){return `<footer class="footer"><div class="container footer-row"><div><strong>Jay Ganesh Agency</strong><div>Private group contribution management · Diwali 2027 · Payments are recorded, never collected by this website</div></div><small>English only · Asia/Kolkata</small></div></footer>`;}

function loginPage(){return `<main class="container page-main"><div class="page-heading"><div class="breadcrumbs">Home / Login</div><h1>Welcome back</h1><p>Customers and Group Leaders use their registered mobile number and 4-digit PIN. Main Admin uses the admin password.</p></div><div class="login-layout">${panel('Login',`${ui.notice}${server&&!server.sheetsConnected?'<div class="callout stop-callout mb-16">Google Sheet connection is not ready. Ask Main Admin to finish setup.</div>':''}<form data-form="login"><div class="field"><label>Registered mobile number</label><input name="mobile" inputmode="numeric" autocomplete="username" maxlength="10" pattern="[6-9][0-9]{9}" required placeholder="10-digit mobile number"></div><div class="field mt-16"><label>4-digit PIN or Admin password</label><input name="password" type="password" autocomplete="current-password" required placeholder="PIN / password"></div><div class="form-actions"><button type="submit" class="btn btn-dark">Log in</button>${btn('New registration','navigate','btn btn-light','register')}</div></form><p class="muted font-small mt-16">Forgot your PIN? Contact the Main Admin. They verify your identity before issuing a temporary PIN.</p>`)}</div></main>`;}

function register(){const open=!!(server&&server.registrationOpen);return `<main class="container page-main"><div class="page-heading"><div class="breadcrumbs">Home / Registration</div><h1>New member registration</h1><p>Complete the details below to request approval from the main organizer.</p></div><div class="two-grid"><div>${panel('Your details',`${ui.notice}<div class="callout ${open?'info':'stop-callout'} mb-16">${open?'Registration is open. Main Admin approval is required after you submit.':'Registration is currently closed. Please contact the organizer.'} No money is transferred by this website.</div><form data-form="register"><div class="form-grid"><div class="field"><label>Full name *</label><input name="name" required maxlength="100" placeholder="Your full name"></div><div class="field"><label>Mobile number *</label><input name="mobile" required pattern="[6-9][0-9]{9}" maxlength="10" inputmode="numeric" placeholder="10-digit mobile"></div><div class="field"><label>Reference person *</label><input name="reference" required maxlength="100" placeholder="Name of your reference"></div><div class="field"><label>Monthly EMI (₹) *</label><input name="emi" type="number" required min="100" max="1000000" step="100" value="500"></div><div class="field"><label>Create 4-digit PIN *</label><input name="pin" type="password" inputmode="numeric" minlength="4" maxlength="4" pattern="[0-9]{4}" autocomplete="new-password" required placeholder="Exactly 4 numbers"></div><div class="field"><label>Confirm 4-digit PIN *</label><input name="confirmPin" type="password" inputmode="numeric" minlength="4" maxlength="4" pattern="[0-9]{4}" autocomplete="new-password" required placeholder="Repeat 4-digit PIN"></div><div class="field full"><label>Comments (optional)</label><textarea name="comments" maxlength="300" placeholder="Anything else the organizer should know?"></textarea></div><div class="field full"><label class="checkrow"><input type="checkbox" required name="agree"><span>I agree to the organizer's terms, privacy notice and payment verification rules.</span></label></div></div><div class="form-actions"><button class="btn btn-dark" type="submit" ${open?'':'disabled'}>Submit registration</button></div></form><p class="muted font-small">Remember your 4-digit PIN. After approval, log in with your mobile number and PIN.</p>`)}</div><div class="content-stack">${panel('What happens next?',`<div class="inline-list"><div><span>1. Submit your details</span>${pill('Registration','neutral')}</div><div><span>2. Main Admin reviews</span>${pill('Pending Approval')}</div><div><span>3. Approved → Customer ID issued</span>${pill('Approved')}</div><div><span>4. Log in with mobile + PIN</span>${pill('Login','neutral')}</div></div>`)}${panel('Registration window',`<div class="inline-list"><div><span>Status</span><strong>${open?'Open':'Closed'}</strong></div><div><span>Controlled by</span><strong>Main Admin</strong></div></div>`)}</div></div></main>`;}

function dashboard(){if(!me)return loginPage();const role=me.role,title=roleNames[role]||'Portal';const list=(role==='admin'?tabs.admin:role==='leader'?tabs.leader:tabs.customer);if(!list.some(t=>t[0]===ui.tab))ui.tab='overview';
 return `<main class="container page-main"><div class="page-heading"><div class="breadcrumbs">Portal / ${e(title)}</div><h1>${e(title)} dashboard</h1><p>${role==='admin'?'Everything here is read from and saved to your Google Sheet.':`Signed in${me.customerId?' · Customer ID '+e(me.customerId):''}`}</p></div><div class="grid-layout"><aside class="sidebar"><h4>${e(title)} menu</h4>${list.map(([k,v])=>`<button class="${ui.tab===k?'active':''}" data-action="tab" data-id="${k}">${v}</button>`).join('')}</aside><div class="content-stack" id="tab-body">${panel('Loading',`<p class="muted">Reading Google Sheet…</p>`)}</div></div></main>`;}

/* ---------- Admin ---------- */
async function adminTab(t){
 if(t==='overview'){const o=await api('admin.overview');
  return `<div class="four-grid">${kpi('Pending registrations','Awaiting your review',String(o.pendingRegistrations))}${kpi('Customers','Approved members',String(o.customers))}${kpi('Groups','Organizer-level totals',String(o.groups))}${kpi('Total monthly group EMI','Members assigned to groups',rupee(o.monthlyGroupEmi))}</div>
  <div class="banner-card"><div><h2>Welcome, Main Admin</h2><p>Registration is <b>${server&&server.registrationOpen?'Live':'Stopped'}</b> · Payment entries are <b>${server&&server.paymentEntriesOpen?'Live':'Stopped'}</b> · ${o.pendingCollections} group collection(s) awaiting verification.</p></div>${btn('Settings & controls','tab','btn btn-primary','settings')}</div>
  ${panel('Quick actions',`<div class="inline-list"><div><span>Review new registrations</span>${btn(`Registrations (${o.pendingRegistrations})`,'tab','btn btn-light btn-small','registrations')}</div><div><span>Verify group collections</span>${btn(`Group collections (${o.pendingCollections})`,'tab','btn btn-light btn-small','payments')}</div><div><span>Create groups and appoint leaders</span>${btn('Groups','tab','btn btn-light btn-small','groups')}</div></div>`)}`;}
 if(t==='orders')return adminOrdersTab();
 if(t==='registrations'){const r=await api('admin.registrations');return panel('Registration requests',regTable([...r.requests].reverse()));}
 if(t==='customers'){const c=await api('admin.customers');return panel('Customers',`<p class="muted font-small">Individual payments are verified by each Group Leader.</p>${table(['Customer ID','Name','Mobile','Group','Status'],c.customers.map(x=>tr(`<strong>${e(x.id)}</strong>`,e(x.name),e(x.mobile),e(x.groupId||'Not assigned'),pill(x.status||'Approved'))),'No customers yet. Approved registrations appear here.')}`);}
 if(t==='groups'){const [g,c]=await Promise.all([api('admin.groups'),api('admin.customers')]);const groups=g.groups,cust=c.customers;const gOpts=groups.map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join(''),cOpts=cust.map(x=>`<option value="${e(x.id)}">${e(x.name)} (${e(x.id)})</option>`).join('');
  return `${panel('Groups',table(['Group','Leader','Members','Total monthly EMI','Verified collection'],groups.map(x=>tr(`<strong>${e(x.name)}</strong> <span class="muted">${e(x.id)}</span>`,e(x.leaderCustomerId||'Not appointed'),e(x.members),`<strong>${rupee(x.totalMonthlyEmi)}</strong>`,rupee(x.verifiedCash))),'No groups yet.'))}
  <div class="two-grid">${panel('Create group',`<form data-form="groupCreate"><div class="field"><label>Group name</label><input name="name" required maxlength="80" placeholder="Enter group name"></div><div class="field mt-16"><label>Reference / area</label><input name="reference" maxlength="80" placeholder="Optional"></div><div class="form-actions"><button class="btn btn-dark btn-small" type="submit">Create group</button></div></form>`)}
  ${panel('Assign customer to group',groups.length&&cust.length?`<form data-form="assign"><div class="field"><label>Customer</label><select name="customerId" required>${cOpts}</select></div><div class="field mt-16"><label>Group</label><select name="groupId" required>${gOpts}</select></div><div class="form-actions"><button class="btn btn-dark btn-small" type="submit">Assign</button></div></form>`:'<p class="muted">Create a group and approve customers first.</p>')}</div>
  ${panel('Appoint Group Leader',groups.length&&cust.length?`<p class="muted font-small">Assign the customer to the group first. Appointing a leader ends their current login session.</p><form data-form="appointLeader" class="form-grid"><div class="field"><label>Group</label><select name="groupId" required>${gOpts}</select></div><div class="field"><label>Leader (approved customer)</label><select name="customerId" required>${cOpts}</select></div><div><button class="btn btn-dark btn-small" type="submit">Appoint leader</button></div></form>`:'<p class="muted">Needs at least one group and one approved customer.</p>')}`;}
 if(t==='payments'){const d=await api('admin.collections');return panel('Group Leader collections',`<div class="callout info mb-16">Only group totals appear here. Confirm you have received the <b>full group amount</b> before verifying.</div>${table(['Group','Amount','Payments','Remittance','Status','Review'],[...d.collections].reverse().map(x=>tr(`<strong>${e(x.groupName)}</strong><div class="muted">${e(x.id)}</div>`,`<strong>${rupee(x.amount)}</strong>`,e(x.paymentCount),`${e(x.remittanceMethod)}<div class="muted">${e(x.remittanceReference)}</div>`,pill(x.status),x.status==='Awaiting Admin'?`${btn('Verify total','verifyCollection','btn btn-dark btn-small',x.id)} ${btn('Reject','rejectCollection','btn btn-light btn-small',x.id)}`:'—')),'No group collections submitted yet.')}`);}
 if(t==='security')return panel('Reset customer 4-digit PIN',`<p class="muted font-small">Check the customer's identity outside the website first. A temporary PIN is shown once; the customer must change it after login. Every reset is recorded in Audit_Log.</p>${ui.issuedPin?`<div class="callout info mt-16"><b>Temporary PIN (shown once):</b> ${e(ui.issuedPin.mobile)} · <strong>${e(ui.issuedPin.pin)}</strong><div>Share privately with the verified customer.</div></div>`:''}<form data-form="resetPin" class="mt-16"><div class="field"><label>Registered mobile</label><input name="mobile" pattern="[6-9][0-9]{9}" inputmode="numeric" maxlength="10" required></div><div class="field mt-16"><label>Identity check details / reason (10+ characters)</label><textarea name="reason" minlength="10" maxlength="200" required></textarea></div><div class="field mt-16"><label class="checkrow"><input name="identityVerified" type="checkbox" required><span>I have independently confirmed this customer's identity.</span></label></div><div class="form-actions"><button class="btn btn-dark" type="submit">Issue temporary PIN</button></div></form>`);
 if(t==='settings'){const d=await api('admin.settings');server={...server,...d};
  const state=(on,open)=>open?pill('Live',''):on?pill('Needs policy approval','pending'):pill('Stop','stop');
  const rows=[['registration','Registration','New member registrations',d.registrationEnabled,d.registrationOpen],['payment','EMI submissions (customer payment entries)','Customers and leaders record EMI already paid',d.paymentEntriesEnabled,d.paymentEntriesOpen],['collections','Group Leader collection processing','Leaders acknowledge payments and submit group totals',d.groupCollectionsEnabled,d.groupCollectionsOpen],['orders','Order collection','Customers choose boxes / PDF lists; Main Admin approves',d.ordersEnabled,d.ordersOpen]];
  return `${panel('Live / Stop controls',`<div class="inline-list">${rows.map(([k,name,desc,on,open])=>`<div><div><strong>${name}</strong><div class="muted">${e(desc)}</div></div><div class="row-between">${state(on,open)} ${btn(on?'Stop':'Go Live','toggle','btn btn-light btn-small',k+':'+(on?'off':'on'))}</div></div>`).join('')}</div><p class="muted font-small mt-16">Saved to the <b>Settings</b> worksheet and enforced by the server. There are no automatic dates: each control stays Live until you press Stop.</p>`)}
  ${panel('Policy approvals',`<div class="inline-list"><div><div><strong>Registration terms & privacy notice</strong><div class="muted">Needed before Registration can go live</div></div><div class="row-between">${d.registrationTermsConfirmed?pill('Approved',''):pill('Not approved','stop')} ${d.registrationTermsConfirmed?btn('Withdraw','policy','btn btn-light btn-small','registrationTermsConfirmed:off'):''}</div></div><div><div><strong>Payment, refund & incomplete-EMI rules</strong><div class="muted">Needed before EMI submissions or collections can go live</div></div><div class="row-between">${d.paymentPolicyConfirmed?pill('Approved',''):pill('Not approved','stop')} ${d.paymentPolicyConfirmed?btn('Withdraw','policy','btn btn-light btn-small','paymentPolicyConfirmed:off'):''}</div></div><div><div><strong>Order terms & fireworks legal clearance</strong><div class="muted">Needed before Order collection can go live</div></div><div class="row-between">${d.orderPolicyConfirmed?pill('Approved',''):pill('Not approved','stop')} ${d.orderPolicyConfirmed?btn('Withdraw','policy','btn btn-light btn-small','orderPolicyConfirmed:off'):''}</div></div></div>`)}
  ${panel('Administrative audit trail',`<p class="muted font-small">Every setting change, approval, rejection and PIN reset is recorded in the <b>Audit_Log</b> worksheet of your Google Sheet.</p>`)}
  ${panel('Refund & legal policy',`<div class="callout">This website never collects money: EMI and extra payments are made to the Group Leader or Main Admin and only recorded here. Automatic refunds are not available. Turn Order collection live only after your order terms and fireworks sale licences / legal clearance are in place.</div>`)}`;}
 return '';
}
const regTable=list=>table(['Name','Reference','Monthly EMI','Received','Status','Action'],list.map(x=>tr(`<strong>${e(x.name)}</strong><div class="muted">${e(x.mobile)}</div>${x.comments?`<div class="muted font-small">${e(x.comments)}</div>`:''}`,e(x.reference),rupee(x.emi),when(x.createdAt),pill(x.status),x.status==='Pending Approval'?`${btn('Approve','approve','btn btn-dark btn-small',x.id)} ${btn('Reject','reject','btn btn-light btn-small',x.id)}`:'—')),'No registration requests.');

/* ---------- Customer ---------- */
async function customerTab(t,asLeader=false){
 if(me.mustChangePin)t='pin';
 if(t==='pin')return panel(me.mustChangePin?'Change your temporary PIN before continuing':'Change your PIN',`<form data-form="changePin" class="form-grid">${pinFields}<div><button class="btn btn-dark" type="submit">Save PIN</button></div></form>`);
 if(t==='order')return myOrderTab(asLeader);
 const d=await api('customer.dashboard'),c=d.customer;
 if(t==='overview')return `<div class="four-grid">${kpi('Customer ID','Your permanent ID',c.id)}${kpi('Monthly EMI','Installments 2–9',rupee(c.emi))}${kpi('Verified cash','Confirmed via group collection',rupee(d.verifiedCash))}${kpi('Eligible credit so far','Excludes packing charge',rupee(d.availableCredit))}</div><div class="banner-card"><div><h2>Welcome, ${e(c.name)}</h2><p>Group: <b>${d.group?e(d.group.name):'Awaiting assignment'}</b> · First installment ${rupee(c.emi*1.5)} · Total planned ${rupee(c.emi*9.5)} over nine installments.</p></div>${btn(asLeader?'Record my payment':'Record a payment','tab','btn btn-primary','record')}</div>${panel('How verification works',`<div class="callout info">${asLeader?'As Group Leader, your own payment is marked <b>Leader Self-Declared</b>. You cannot approve it yourself: include it in your next group collection, and it becomes verified only when Main Admin verifies the combined total.':'Your payment entry goes to your Group Leader first.'} It counts as verified EMI only after the Main Admin verifies the leader's combined group collection. Packing charge is not order credit; the bonus is not automatic.</div>`)}`;
 if(t==='record'){const open=!!(server&&server.paymentEntriesOpen);return panel(asLeader?'Record my EMI payment':'Record a payment',`<div class="callout ${open?'info':'stop-callout'} mb-16">${open?'Payment entries are open. '+(asLeader?'Record your own EMI. It will be marked Leader Self-Declared and must be included in a group collection.':'This only records money you already paid to your Group Leader.'):'Payment entries are currently closed by Main Admin or the date window.'}</div><form data-form="payment" class="form-grid"><div class="field"><label>EMI installment</label><select name="installment">${Array.from({length:9},(_,i)=>`<option value="${i+1}">${i+1} — ${i===0?'First installment':'Regular'} (${rupee(c.emi*(i===0?1.5:1))})</option>`).join('')}</select></div><div class="field"><label>Amount paid (₹)</label><input name="amount" type="number" min="1" step="0.01" required></div><div class="field"><label>Payment method</label><select name="mode"><option>Cash</option><option>Online</option></select></div><div class="field"><label>Reference / receipt (optional)</label><input name="reference" maxlength="120"></div><div><button class="btn btn-dark" type="submit" ${open?'':'disabled'}>Submit payment entry</button></div></form>`);}
 if(t==='history')return panel('My payment entries',`<p class="muted font-small">An entry is not verified EMI until the Main Admin verifies its group collection.</p>${table(['Date','Installment','Amount','Method','Reference','Status'],[...d.payments].reverse().map(x=>tr(when(x.createdAt),e(x.installment),rupee(x.amount),e(x.mode),e(x.reference),pill(x.status))),'No payment entries yet.')}`);
 return '';
}

/* ---------- Group Leader ---------- */
async function leaderTab(t){
 if(me.mustChangePin)t='pin';
 if(t==='myemi')return customerTab('overview',true);
 if(t==='myorder')return myOrderTab(true);
 if(t==='grouporders')return leaderGroupOrders();
 if(t==='record'||t==='history')return customerTab(t,true);
 if(t==='pin')return panel('Change PIN',`<form data-form="changePin" class="form-grid">${pinFields}<div><button class="btn btn-dark" type="submit">Save PIN</button></div></form>`);
 const d=await api('leader.queue'),g=d.group;
 if(t==='overview')return `<div class="four-grid">${kpi('Group',e(g.id||''),g.name)}${kpi('Members','Assigned to you',String(g.members))}${kpi('Group monthly EMI','Sum of member EMIs',rupee(g.totalMonthlyEmi))}${kpi('Verified collections','Confirmed by Main Admin',rupee(g.verifiedCash))}</div>${panel('Assigned members',table(['Customer ID','Name','Monthly EMI'],d.members.map(c=>tr(`<strong>${e(c.id)}</strong>`,e(c.name),rupee(c.emi))),'No members assigned yet.'))}`;
 if(t==='review')return panel('Member payment verification',`<p class="muted font-small">Check each member's cash or online receipt. Only acknowledged entries can be included in a group collection.</p>${table(['Member','Installment','Amount','Method / reference','Status','Action'],[...d.payments].reverse().map(x=>tr(`<strong>${e(x.memberName)}</strong>${x.isOwnPayment?' '+pill('You','neutral'):''}`,e(x.installment),rupee(x.amount),`${e(x.mode)}<div class="muted">${e(x.reference)}</div>`,pill(x.status),x.isOwnPayment?'<span class="muted font-small">Your own payment · include in group collection</span>':x.status==='Awaiting Leader'?`${btn('Acknowledge','ackPayment','btn btn-dark btn-small',x.id)} ${btn('Reject','rejectPayment','btn btn-light btn-small',x.id)}`:'—')),'No payment entries yet.')}`);
 if(t==='submit'){const ok=d.payments.filter(x=>x.status==='Leader Verified'||(x.isOwnPayment&&['Leader Self-Declared','Awaiting Leader'].includes(x.status)));return `${panel('Submit combined group collection',ok.length?`<div class="callout info mb-16">Select acknowledged member payments (and your own self-declared EMI) and remit the <b>exact combined amount</b> to the Main Admin.</div><form data-form="collection">${ok.map(x=>`<label class="checkrow"><input type="checkbox" class="batchCheck" value="${e(x.id)}" data-amount="${e(x.amount)}" checked><span>${e(x.memberName)}${x.isOwnPayment?' (you, self-declared)':''} · EMI ${e(x.installment)} · ${rupee(x.amount)}</span></label>`).join('')}<div class="summary-line mt-16"><span>Combined amount</span><strong id="batchTotal">${rupee(ok.reduce((s,x)=>s+Number(x.amount),0))}</strong></div><div class="form-grid mt-16"><div class="field"><label>Remittance method</label><select name="remittanceMethod"><option>Cash</option><option>Online</option></select></div><div class="field"><label>Remittance reference (optional)</label><input name="remittanceReference" maxlength="150"></div></div><div class="form-actions"><button class="btn btn-dark" type="submit">Submit group collection</button></div></form>`:'<p class="muted">No acknowledged member payments or own EMI entries are ready to submit.</p>')}${panel('Previous group submissions',table(['Date','Total','Payments','Status'],[...d.collections].reverse().map(x=>tr(when(x.createdAt),rupee(x.amount),e(x.paymentCount),pill(x.status))),'No submissions yet.'))}`;}
 return '';
}

/* ---------- Orders (customer / leader own order) ---------- */
const orderPill=o=>`${pill(o.status==='Finalized'?'Approved':o.status==='Locked'?'Locked':'Draft',o.status==='Finalized'?'':o.status==='Locked'?'pending':'neutral')} ${o.status==='Finalized'?'':pill(o.financial.financialStatus,o.financial.financialStatus==='Validated'?'':o.financial.financialStatus==='Under-credit'?'stop':'pending')}`;
function orderMoney(f){return `<div class="four-grid">${kpi('Available credit','Verified EMI contributions',rupee(f.availableCredit))}${kpi('Order value','At scheme price (50%)',rupee(f.discountedOrderValue))}${kpi(f.unusedCredit>0?'Unused credit':'Extra payable',f.unusedCredit>0?'Add items to use it':'Paid to Main Admin',rupee(f.unusedCredit>0?f.unusedCredit:f.extraPayable))}${kpi('Still to pay','After recorded extra payments',rupee(f.finalOutstanding))}</div>`;}
function orderBoxesTable(o){return table(['Box','Advertised','Your price','Qty','Subtotal'],o.boxes.map(b=>tr(`<strong>${e(b.name)}</strong>`,rupee(b.advertised),rupee(b.scheme),e(b.quantity),`<strong>${rupee(b.scheme*b.quantity)}</strong>`)),'No boxes selected.');}
function orderUploadsTable(o,admin){return table(['PDF list','Uploaded','Status','Advertised value',...(admin?['Action']:[])],o.uploads.map(u=>tr(`${admin&&u.url?`<a href="${e(u.url)}" target="_blank" rel="noopener">${e(u.filename)}</a>`:e(u.filename)}`,when(u.createdAt),pill(u.status==='Approved'?'Priced':'Pricing pending',u.status==='Approved'?'':'pending'),u.advertisedListValue==null?'—':rupee(u.advertisedListValue),...(admin?[o.status==='Finalized'?'—':`<form data-form="priceList" class="row-between"><input type="hidden" name="uploadId" value="${e(u.id)}"><input name="advertisedListValue" type="number" min="0" step="1" required placeholder="₹ advertised" style="max-width:130px" value="${u.advertisedListValue??''}"><button class="btn btn-dark btn-small" type="submit">${u.status==='Approved'?'Update':'Set price'}</button></form>`]:[]))),'No PDF lists uploaded.');}
async function myOrderTab(asLeader){
 const d=await api('order.mine'),o=d.order,open=d.ordersOpen;
 if(!o)return panel('My Diwali order',`<div class="callout ${open?'info':'stop-callout'} mb-16">${open?'Order collection is open. You can place one order. Your verified EMI credit pays for boxes at the scheme price (50% of advertised).':'Order collection is currently stopped by Main Admin.'}</div><div class="inline-list"><div><span>Your available credit now</span><strong>${rupee(d.account.availableCredit)}</strong></div><div><span>Verified cash paid</span><strong>${rupee(d.account.paidCash)}</strong></div></div><div class="form-actions"><button class="btn btn-dark" data-action="orderCreate" ${open?'':'disabled'}>Start my order</button></div>`);
 const f=o.financial,draft=o.status==='Draft',editable=draft&&open;
 const qty=id=>(o.boxes.find(b=>b.pricingId===id)||{}).quantity||0;
 const editor=editable?panel('Choose your boxes',`<form data-form="orderDraft"><input type="hidden" name="orderId" value="${e(o.id)}"><div class="form-grid"><div class="field"><label>Order type</label><select name="type">${d.orderTypes.map(t=>`<option ${o.type===t?'selected':''}>${e(t)}</option>`).join('')}</select></div><div class="field"><label>Number of PDF lists (for "Only List" / "Both")</label><input name="listCount" type="number" min="0" max="10" step="1" value="${e(o.listCount)}"></div></div>
  ${table(['Box','Advertised','Your price (50%)','Quantity'],d.pricing.map(p=>tr(`<strong>${e(p.name)}</strong>`,rupee(p.advertised),`<strong>${rupee(p.scheme)}</strong>`,`<input class="box-qty" data-scheme="${e(p.scheme)}" name="qty_${e(p.id)}" type="number" min="0" max="999" step="1" value="${qty(p.id)}" style="max-width:90px">`)))}
  <div class="summary-line mt-16"><span>Boxes at your price (before saving)</span><strong id="boxPreview">${rupee(o.boxes.reduce((s,b)=>s+b.scheme*b.quantity,0))}</strong></div><div class="form-actions"><button class="btn btn-dark" type="submit">Save order</button></div></form>`):'';
 const needLists=o.type!=='Only Box';
 const uploads=needLists?panel('PDF lists',`${editable&&o.uploads.length<o.listCount?`<form data-form="orderUpload" class="row-between mb-16"><input type="hidden" name="orderId" value="${e(o.id)}"><input type="file" name="pdf" accept="application/pdf,.pdf" required><button class="btn btn-dark btn-small" type="submit">Upload PDF</button></form><p class="muted font-small">${o.uploads.length} of ${o.listCount} uploaded · PDF only, up to 3 MB. Main Admin sets each list's value.</p>`:''}${orderUploadsTable(o,false)}`):'';
 const lockPanel=draft?panel('Lock your order',`<p class="muted font-small">Locking sends your order to Main Admin. You cannot change it afterwards. ${f.unusedCredit>0&&!f.pricingPending?`<b>You still have ${rupee(f.unusedCredit)} unused credit</b>: add items before locking.`:''} ${f.extraPayable>0?`Your order is ${rupee(f.extraPayable)} above your credit; pay this extra amount to Main Admin.`:''}</p><div class="form-actions">${btn('Lock order','orderLock','btn btn-dark',o.id)}</div>`):'';
 return `${panel('My Diwali order',`<div class="row-between"><div><strong>${e(o.id)}</strong> · ${e(o.type)}</div><div>${orderPill(o)}</div></div>${draft&&!open?'<div class="callout stop-callout mt-16">Order collection is stopped by Main Admin, so changes are paused.</div>':''}${o.status==='Locked'?'<div class="callout info mt-16">Locked and waiting for Main Admin review.</div>':''}${o.status==='Finalized'?'<div class="callout info mt-16">Your order is approved by Main Admin.</div>':''}`)}
 ${orderMoney(f)}${editor}${!editable?panel('Boxes',orderBoxesTable(o)):''}${uploads}${lockPanel}`;
}
async function leaderGroupOrders(){const d=await api('leader.orders');return panel('Group members’ orders',`<p class="muted font-small">Read-only. Main Admin reviews and approves orders.</p>${table(['Member','Order','Type','Status','Order value','Still to pay'],d.orders.map(o=>tr(`<strong>${e(o.customerName)}</strong>`,e(o.id),e(o.type),orderPill(o),rupee(o.financial.discountedOrderValue),rupee(o.financial.finalOutstanding))),'No orders from your group yet.')}`);}

/* ---------- Orders (Main Admin) ---------- */
async function adminOrdersTab(){
 const d=await api('admin.orders'),orders=[...d.orders].reverse(),sel=orders.find(o=>o.id===ui.orderId);
 const list=panel('Orders',table(['Customer','Order','Type','Status','Value','Credit','Still to pay',''],orders.map(o=>tr(`<strong>${e(o.customerName)}</strong><div class="muted">${e(o.customerId)}</div>`,e(o.id),e(o.type),orderPill(o),rupee(o.financial.discountedOrderValue),rupee(o.financial.availableCredit),`<strong>${rupee(o.financial.finalOutstanding)}</strong>`,btn(sel&&sel.id===o.id?'Close':'Open','orderOpen','btn btn-light btn-small',sel&&sel.id===o.id?'':o.id))),'No orders yet.'));
 if(!sel)return list;
 const f=sel.financial,locked=sel.status==='Locked',ok=locked&&!f.pricingPending&&f.unusedCredit<=0&&f.finalOutstanding<=0;
 const boxOpts=d.pricing.map(p=>`<option value="${e(p.id)}">${e(p.name)} (${rupee(p.scheme)})</option>`).join('');
 return `${list}${panel(`Order ${e(sel.id)} · ${e(sel.customerName)}`,`<div class="row-between mb-16"><span>${e(sel.type)}${sel.lockedAt?' · locked '+when(sel.lockedAt):''}</span><span>${orderPill(sel)}</span></div>${orderMoney(f)}<h3 class="mt-16">Boxes</h3>${orderBoxesTable(sel)}${sel.type!=='Only Box'?`<h3 class="mt-16">PDF lists</h3>${orderUploadsTable(sel,true)}<p class="muted font-small">Open each PDF, then enter its total advertised value. The customer pays 50% of it from credit.</p>`:''}${sel.extras.length?`<h3 class="mt-16">Extra payments received</h3>${table(['Date','Amount','Method','Reference'],sel.extras.map(x=>tr(when(x.createdAt),rupee(x.amount),e(x.mode),e(x.reference))))}`:''}`)}
 ${locked?`<div class="two-grid">${panel('Record extra payment received',f.finalOutstanding>0?`<form data-form="recordExtra"><input type="hidden" name="orderId" value="${e(sel.id)}"><div class="field"><label>Amount received (₹)</label><input name="amount" type="number" min="1" step="0.01" required value="${f.finalOutstanding}"></div><div class="field mt-16"><label>Method</label><select name="mode"><option>Cash</option><option>Online</option></select></div><div class="field mt-16"><label>Reference (optional)</label><input name="reference" maxlength="120"></div><div class="form-actions"><button class="btn btn-dark btn-small" type="submit">Record payment</button></div></form>`:'<p class="muted">Nothing extra is due.</p>')}
 ${panel('Correct box quantity',`<form data-form="correctOrder"><input type="hidden" name="orderId" value="${e(sel.id)}"><div class="field"><label>Box</label><select name="pricingId">${boxOpts}</select></div><div class="field mt-16"><label>New quantity</label><input name="quantity" type="number" min="0" max="999" step="1" required></div><div class="field mt-16"><label>Reason (10+ characters, saved in Audit_Log)</label><input name="reason" minlength="10" maxlength="300" required></div><div class="form-actions"><button class="btn btn-light btn-small" type="submit">Save correction</button></div></form>`)}</div>
 ${panel('Approve order',`<p class="muted font-small">${ok?'All checks pass: lists priced, full credit used and extra payment recorded.':f.pricingPending?'Set the value of every PDF list first.':f.unusedCredit>0?`The order leaves ${rupee(f.unusedCredit)} credit unused. Correct the quantities or ask the customer.`:`Record the extra payment of ${rupee(f.finalOutstanding)} first.`}</p><div class="form-actions"><button class="btn btn-dark" data-action="orderApprove" data-id="${e(sel.id)}" ${ok?'':'disabled'}>Approve order</button></div>`)}`:''}`;
}

/* ---------- Rendering ---------- */
function toast(m){ui.toast=m;const old=$('toast');if(old)old.remove();document.querySelector('.app-shell')?.insertAdjacentHTML('beforeend',`<div id="toast" class="toast">${e(m)}</div>`);setTimeout(()=>{if(ui.toast===m){ui.toast='';$('toast')?.remove()}},4500)}
function render(){const token=++renderToken;const body=ui.page==='home'?home():ui.page==='scheme'?scheme():ui.page==='register'?register():ui.page==='login'?loginPage():dashboard();
 $('app').innerHTML=`<div class="app-shell">${header()}${body}${footer()}${ui.toast?`<div id="toast" class="toast">${e(ui.toast)}</div>`:''}</div>`;ui.notice='';
 const amt=$('calc-amount'),sl=$('calc-slider');const upd=v=>{ui.calc=Math.max(100,Math.round((Number(v)||100)/100)*100);render()};if(amt)amt.onchange=ev=>upd(ev.target.value);if(sl)sl.onchange=ev=>upd(ev.target.value);
 if(ui.page==='dashboard'&&me)loadTab(token);}
async function loadTab(token){const target=$('tab-body');try{const html=me.role==='admin'?await adminTab(ui.tab):me.role==='leader'?await leaderTab(ui.tab):await customerTab(ui.tab);if(token!==renderToken)return;target.innerHTML=html;
  const boxes=target.querySelectorAll('.box-qty');boxes.forEach(x=>x.oninput=()=>{const el=$('boxPreview');if(el)el.textContent=rupee([...boxes].reduce((s,n)=>s+Number(n.dataset.scheme)*Math.max(0,Number(n.value)||0),0))});
  target.querySelectorAll('.batchCheck').forEach(x=>x.onchange=()=>{$('batchTotal').textContent=rupee([...target.querySelectorAll('.batchCheck:checked')].reduce((s,n)=>s+Number(n.dataset.amount),0))});
 }catch(err){if(token!==renderToken)return;if(err.status===401){me=null;ui.page='login';ui.notice='<div class="callout info mb-16">Your session ended. Please log in again.</div>';return render()}target.innerHTML=panel('Could not load',errBox(err))}}
function navigate(p){ui.page=p;window.scrollTo(0,0);render()}
async function refreshStatus(){try{server=await api('status')}catch{server=null}}

async function onAction(act,id){try{switch(act){
 case 'home':return navigate('home');
 case 'navigate':return navigate(id);
 case 'customer':case 'dashboard':return navigate(me?'dashboard':'login');
 case 'tab':ui.tab=id;ui.issuedPin=null;return render();
 case 'logout':try{await api('logout')}catch{}me=null;ui.tab='overview';navigate('home');return toast('Logged out.');
 case 'approve':if(!confirm('Approve this registration and create a permanent Customer ID?'))return;{const r=await api('admin.approve',{id});toast('Approved · Customer ID '+r.customerId)}return render();
 case 'reject':{const reason=prompt('Reason for rejecting this registration?');if(reason===null)return;await api('admin.reject',{id,reason});toast('Registration rejected.')}return render();
 case 'verifyCollection':if(!confirm('Have you received and reconciled the entire group amount?'))return;await api('admin.verifyCollection',{id});toast('Group collection verified.');return render();
 case 'rejectCollection':{const reason=prompt('Why is this group collection rejected?');if(reason===null)return;await api('admin.rejectCollection',{id,reason});toast('Group collection rejected.')}return render();
 case 'ackPayment':if(!confirm('Have you received and checked this payment?'))return;await api('leader.ackPayment',{id});toast('Payment acknowledged.');return render();
 case 'rejectPayment':{const reason=prompt('Reason for rejection?');if(reason===null)return;await api('leader.rejectPayment',{id,reason});toast('Payment rejected.')}return render();
 case 'orderCreate':await api('order.create');toast('Order started. Choose your boxes.');return render();
 case 'orderLock':if(!confirm('Lock your order? You cannot change it afterwards.'))return;{const r=await api('order.lock',{orderId:id});toast(r.financialStatus==='Pricing Pending'?'Order locked · waiting for Main Admin to price your PDF list(s).':'Order locked · sent to Main Admin.')}return render();
 case 'orderOpen':ui.orderId=id;return render();
 case 'orderApprove':if(!confirm('Approve this order? This is final.'))return;await api('admin.approveOrder',{orderId:id});toast('Order approved.');return render();
 case 'policy':{const [key]=id.split(':');if(!confirm('Withdraw this approval? Related controls will stop working until it is approved again.'))return;await api('admin.updateSetting',{key,enabled:false});await refreshStatus();toast('Approval withdrawn.')}return render();
 case 'toggle':{const [k,dir]=id.split(':'),on=dir==='on';const map={registration:['registrationEnabled','registrationTermsConfirmed','Registration'],payment:['paymentEntriesEnabled','paymentPolicyConfirmed','EMI submissions'],collections:['groupCollectionsEnabled','paymentPolicyConfirmed','Group collection processing'],orders:['ordersEnabled','orderPolicyConfirmed','Order collection']};const [key,policy,label]=map[k];
  if(on){const s=await api('admin.settings');
   if(!s[policy]){const text=policy==='orderPolicyConfirmed'?'Before going live, confirm:\n\nOrder terms are approved, and you hold the licences / legal clearance needed to sell fireworks to these customers.\n\nClick OK to confirm and turn Order collection live.':policy==='registrationTermsConfirmed'?'Before going live, confirm:\n\nYour registration terms and privacy notice are approved and available to customers.\n\nClick OK to confirm and turn Registration live.':'Before going live, confirm:\n\nPayment, refund and incomplete-EMI rules, and any legal requirements, have been reviewed and approved.\n\nClick OK to confirm and continue.';if(!confirm(text))return;await api('admin.updateSetting',{key:policy,enabled:true,acknowledged:true})}
   else if(!confirm(`Turn ${label} live?`))return;
   const r=await api('admin.updateSetting',{key,enabled:true});await refreshStatus();
   const open=k==='registration'?r.registrationOpen:k==='payment'?r.paymentEntriesOpen:k==='orders'?r.ordersOpen:r.groupCollectionsOpen;toast(open?`${label} is now live.`:`${label} switched on, but its policy approval is missing.`);
  }else{if(!confirm(`Stop ${label}? New actions stop immediately.`))return;await api('admin.updateSetting',{key,enabled:false});await refreshStatus();toast(`${label} stopped.`)}
  return render();}
}}catch(err){if(err.status===401){me=null;ui.page='login';ui.notice='<div class="callout info mb-16">Your session ended. Please log in again.</div>';return render()}alert(err.message)}}

async function onForm(name,f){const v=Object.fromEntries(new FormData(f).entries());const b=f.querySelector('[type=submit]');if(b)b.disabled=true;
 try{switch(name){
  case 'login':{const d=await api('login',{mobile:v.mobile.trim(),password:v.password});me=d;ui.tab=d.mustChangePin?'pin':'overview';await refreshStatus();navigate('dashboard');return toast('Signed in.');}
  case 'register':{if(v.pin!==v.confirmPin)throw Error('PIN and Confirm PIN must match');const d=await api('registration',{name:v.name,mobile:v.mobile,reference:v.reference,emi:Number(v.emi),pin:v.pin,comments:v.comments,acceptedTerms:v.agree==='on'});ui.notice=`<div class="callout info mb-16">Registration received (${e(d.registrationId||'')}). You can log in after Main Admin approves it.</div>`;return navigate('login');}
  case 'orderDraft':{const boxes=[...f.querySelectorAll('.box-qty')].map(x=>({pricingId:x.name.slice(4),quantity:Number(x.value||0)})).filter(b=>b.quantity>0);const type=v.type;const listCount=type==='Only Box'?0:Math.max(1,Number(v.listCount||1));await api('order.saveDraft',{orderId:v.orderId,type,listCount,boxes});toast('Order saved.');return render();}
  case 'orderUpload':{const file=f.querySelector('input[type=file]').files[0];if(!file)throw Error('Choose a PDF file');if(file.size>3*1024*1024)throw Error('PDF must be smaller than 3 MB');const b64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]||'');r.onerror=()=>no(Error('Could not read the file'));r.readAsDataURL(file)});await api('order.upload',{orderId:v.orderId,filename:file.name,fileBase64:b64});toast('PDF uploaded · Main Admin will set its value.');return render();}
  case 'priceList':await api('admin.priceList',{uploadId:v.uploadId,advertisedListValue:Number(v.advertisedListValue)});toast('List value saved.');return render();
  case 'recordExtra':if(!confirm('Confirm you have received ₹'+v.amount+' for this order?'))return;await api('admin.recordExtra',{orderId:v.orderId,amount:Number(v.amount),mode:v.mode,reference:v.reference});toast('Extra payment recorded.');return render();
  case 'correctOrder':await api('admin.correctOrder',{orderId:v.orderId,pricingId:v.pricingId,quantity:Number(v.quantity),reason:v.reason});toast('Correction saved and logged.');return render();
  case 'groupCreate':await api('admin.groupCreate',{name:v.name,reference:v.reference});toast('Group created.');return render();
  case 'assign':await api('admin.assign',{customerId:v.customerId,groupId:v.groupId});toast('Customer assigned.');return render();
  case 'appointLeader':await api('admin.appointLeader',{customerId:v.customerId,groupId:v.groupId});toast('Group Leader appointed.');return render();
  case 'resetPin':{if(!confirm('Reset this customer’s PIN after identity verification?'))return;const d=await api('admin.resetPin',{mobile:v.mobile,reason:v.reason,identityVerified:v.identityVerified==='on'});ui.issuedPin={mobile:v.mobile,pin:d.temporaryPin};return render();}
  case 'payment':await api('customer.payment',{installment:Number(v.installment),amount:Number(v.amount),mode:v.mode,reference:v.reference});toast(me.role==='leader'?'Your payment is recorded as Leader Self-Declared. Include it in your next group collection.':'Payment entry submitted · awaiting your Group Leader.');ui.tab='history';return render();
  case 'collection':{const boxes=[...f.querySelectorAll('.batchCheck:checked')],ids=boxes.map(x=>x.value),total=boxes.reduce((s,n)=>s+Number(n.dataset.amount),0);if(!ids.length)throw Error('Choose one or more payments');if(!confirm('Have you remitted '+rupee(total)+' to the Main Admin?'))return;await api('leader.collection',{paymentIds:ids,remittanceMethod:v.remittanceMethod,remittanceReference:v.remittanceReference});toast('Group collection submitted for Main Admin verification.');return render();}
  case 'changePin':{if(v.newPin!==v.confirm)throw Error('New PINs do not match');await api('changePin',{currentPin:v.currentPin,newPin:v.newPin});try{await api('logout')}catch{}me=null;ui.notice='<div class="callout info mb-16">PIN changed. Please log in with your new PIN.</div>';return navigate('login');}
 }}catch(err){f.querySelector('.form-error')?.remove();f.insertAdjacentHTML('beforeend',`<div class="form-error mt-16">${errBox(err)}</div>`)}finally{if(b&&document.body.contains(b))b.disabled=false}}

document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;ev.preventDefault();onAction(el.dataset.action,el.dataset.id||'')});
document.addEventListener('submit',ev=>{const f=ev.target.closest('form[data-form]');if(!f)return;ev.preventDefault();onForm(f.dataset.form,f)});
(async function boot(){render();const [,m]=await Promise.all([refreshStatus(),api('me').catch(()=>null)]);me=m&&m.role?m:null;if(me)ui.page='dashboard';render()})();
